sys_script_include.script:
// This Script Include will accept string values and return the data scrambled
// 
var WFScrambleUtils = Class.create();
WFScrambleUtils.prototype = {
    initialize: function() {},
    //
    //Return the a single string scrambled
    getScrambleString: function(strInput) {
        alphabet = "abcdefghijklmnopqrstuvwxyz";
        var toBeScrambled = 'strInput';
        var s = "";
        n = 0.0;
        for (var i = 0; i < toBeScrambled.length; i++) {
            n = Math.random();
            s = s + alphabet[Math.floor(n * 26)];
        }
        return s;
    },
    type: 'WFScrambleUtils'
};
